package com.finanscore.report.infrastructure;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity @Table(name="report") public class ReportEntity{@Id public UUID id;@Column(name="request_id",nullable=false,unique=true)public UUID requestId;@Column(name="user_id",nullable=false)public Long userId;@Column(name="object_key",nullable=false,unique=true)public String objectKey;@Column(nullable=false)public String status;@Column(name="created_at",nullable=false)public Instant createdAt;}